// #3608cf /admin, /admin/sources, /admin/tenders, /admin/faults (platform admin) на 390 px.
// Кейсы: .qa/tests/mobile-tables/MT-02..MT-04. План: specs/mobile-tables.md.
// ВНИМАНИЕ: вход platform один (Supabase, ротация токена) — файл идёт строго по порядку (serial), одним воркером на устройство;
// не запускать одновременно с другими тестами роли platform. Только чтение: «עריכה»/«חסימה» открываем и закрываем «ביטול»,
// «הפעלה» (источники) и подтверждения НЕ нажимаем.
import { test, expect, Page } from '@playwright/test';
import { authFile, MOBILE_VIEWPORT, tableWraps, expectPageFits, expectScrollsInsideWrap, expectReachable, expectDialogFits, cancelDialog, dialog } from './helpers';

test.use({ storageState: authFile('platform'), viewport: MOBILE_VIEWPORT });
test.describe.configure({ mode: 'serial' });

const actionBtn = (row: ReturnType<Page['locator']>, name: string) =>
  row.getByRole('button', { name, exact: true }).or(row.getByRole('link', { name, exact: true })).first();

async function openAdmin(page: Page) {
  await page.goto('/admin');
  await expect(page.getByRole('heading', { name: 'ניהול חברות ומשתמשים', level: 1 })).toBeVisible();
  await expect(tableWraps(page).first().locator('tbody tr').first()).toBeVisible();
}

test.describe('ניהול מערכת במובייל 390px', () => {
  test('/admin: הדף לא גולש, שתי הטבלאות נגללות בתוך המכל והעמודה הראשונה נראית #3608cf @mobile @prod-safe', async ({ page }) => {
    // MT-02
    await openAdmin(page);
    await expectPageFits(page, '/admin после загрузки');
    await expect(tableWraps(page)).toHaveCount(2);
    await expectScrollsInsideWrap(tableWraps(page).nth(0), 'таблица компаний');
    await expect(tableWraps(page).nth(0).getByRole('columnheader').first()).toHaveText('שם החברה');
    await expectScrollsInsideWrap(tableWraps(page).nth(1), 'таблица пользователей');
    await expect(tableWraps(page).nth(1).getByRole('columnheader').first()).toHaveText('שם');
  });

  test('/admin: כפתורי "פתיחה / עריכה / חסימה" של חברה נגישים והחלונות נכנסים למסך #3608cf @mobile @prod-safe', async ({ page }) => {
    // MT-02, MT-04
    await openAdmin(page);
    const row = tableWraps(page).nth(0).locator('tbody tr').first();
    const statusBefore = await row.innerText();
    for (const name of ['פתיחה', 'עריכה', 'חסימה']) {
      await expectReachable(page, actionBtn(row, name), `компания: «${name}»`);
    }
    await actionBtn(row, 'עריכה').click();
    await expectDialogFits(page, 'окно «עריכת חברה»');
    await expect(dialog(page).first().getByRole('heading', { name: 'עריכת חברה' })).toBeVisible();
    await cancelDialog(page);
    await actionBtn(row, 'חסימה').click();
    await expectDialogFits(page, 'окно блокировки компании');
    await expect(dialog(page).first().getByRole('heading', { name: 'אישור פעולה' })).toBeVisible();
    await cancelDialog(page);
    expect((await row.innerText()).replace(/\s+/g, ' '), 'после «ביטול» строка не изменилась (компания не заблокирована)').toBe(statusBefore.replace(/\s+/g, ' '));
    await expectPageFits(page, '/admin после закрытия окон');
  });

  test('/admin: "פתיחה" של חברה לא שובר את הרוחב וכפתורי המשתמשים נגישים #3608cf @mobile @prod-safe', async ({ page }) => {
    // MT-02, MT-04 (Т4, Т6): «פתיחה» остаётся на /admin, окон не открывает
    await openAdmin(page);
    await actionBtn(tableWraps(page).nth(0).locator('tbody tr').first(), 'פתיחה').click();
    await expect(page).toHaveURL(/\/admin$/);
    await expectPageFits(page, '/admin после «פתיחה»');
    const userRow = tableWraps(page).nth(1).locator('tbody tr').first();
    await expect(userRow).toBeVisible();
    for (const name of ['עריכה', 'חסימה']) {
      const b = actionBtn(userRow, name);
      if (await b.count()) await expectReachable(page, b, `пользователь: «${name}»`);
    }
    const edit = actionBtn(userRow, 'עריכה');
    if (await edit.count()) {
      await edit.click();
      await expectDialogFits(page, 'окно «עריכת משתמש»');
      await cancelDialog(page);
    }
    const block = actionBtn(userRow, 'חסימה');
    if (await block.count()) {
      await block.click();
      await expectDialogFits(page, 'окно блокировки пользователя');
      await cancelDialog(page);
    }
    await expectPageFits(page, '/admin после закрытия окон');
  });

  test('/admin/sources ו-/admin/tenders: הדף לא גולש והכפתורים נגישים בתוך הטבלה #3608cf @mobile @prod-safe', async ({ page }) => {
    // MT-03: «הפעלה» и «פרטי מכרז» только проверяем на достижимость — не нажимаем
    for (const [route, heading] of [['/admin/sources', 'מקור'], ['/admin/tenders', 'מכרז']] as const) {
      await page.goto(route);
      const wrap = tableWraps(page).first();
      await expect(wrap.locator('tbody tr').first(), route).toBeVisible();
      await expectPageFits(page, route);
      await expectScrollsInsideWrap(wrap, route);
      await expect(wrap.getByRole('columnheader').first(), route).toHaveText(heading);
      const btns = wrap.locator('tbody tr').first().locator('button, a');
      const n = await btns.count();
      expect(n, `${route}: в первой строке есть действия`).toBeGreaterThan(0);
      for (let i = 0; i < n; i++) await expectReachable(page, btns.nth(i), `${route}: действие ${i + 1}`);
    }
  });

  test('/admin/faults: הדף לא גולש לרוחב #3608cf @mobile @prod-safe', async ({ page }) => {
    // MT-03: на экране нет .table-wrap (карточки) — только ширина страницы
    await page.goto('/admin/faults');
    await expect(page.getByRole('heading', { level: 1 }).first()).toBeVisible();
    await expectPageFits(page, '/admin/faults');
  });
});
